from pathlib import Path
import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np
z=np.load('/challenge/observations.npz'); x=z['tokens'];p=z['probabilities'];p/=p.sum(-1,keepdims=True)
f=np.load('/output/analysis.npz')['f'];I=np.eye(16)
row=np.repeat(np.arange(128),21);t=np.tile(np.arange(3,24),128);src=x[row,t-3];q=p[:,3:].reshape(-1,16);target=f[src]
rng=np.random.default_rng(42);o=rng.permutation(128);tr=np.isin(row,o[:96]);te=~tr
Y=np.log(q);Y-=Y.mean(1,keepdims=True)
def softmax(a):
 a=a-a.max(1,keepdims=True);a=np.exp(a);return a/a.sum(1,keepdims=True)
def score(a,b): return [float(np.mean(np.sum(a*np.log(a/b),axis=-1))),float(np.mean(np.abs(a-b).sum(-1)/2))]
def design(lags=(),position=False):
 a=[np.ones((len(row),1)),I[src]]
 if position:a.append(np.eye(21)[t-3])
 for lag in lags:
  a.append(np.eye(17)[np.where(t>=lag,x[row,np.maximum(t-lag,0)],16)])
 return np.concatenate(a,axis=1)
for pos,lags in [(False,()),(True,()),(True,(1,)),(True,(2,)),(True,(1,2)),(True,(1,2,4)),(True,(1,2,4,5,6)),(True,tuple(a for a in range(1,10) if a!=3))]:
 D=design(lags,pos)
 for ridge in [1.,10.]:
  w=np.linalg.solve(D[tr].T@D[tr]+ridge*np.eye(D.shape[1]),D[tr].T@Y[tr]);pred=softmax(D[te]@w)
  print('CLR',pos,lags,ridge,'params',w.size,'heldout',score(q[te],pred))
print('residual scalar confidence: additive source,position,recent tokens')
c=q[np.arange(len(q)),target];yc=np.log(c/(1-c));
for pos,lags in [(False,()),(True,()),(True,(1,)),(True,(2,)),(True,(1,2)),(True,(1,2,4,5,6)),(True,tuple(a for a in range(1,10) if a!=3))]:
 D=design(lags,pos)
 for ridge in [0.1,1.,10.]:
  w=np.linalg.solve(D[tr].T@D[tr]+ridge*np.eye(D.shape[1]),D[tr].T@yc[tr]);yp=1/(1+np.exp(-D[te]@w));mse=np.mean((yc[te]-D[te]@w)**2)
  print('confidence',pos,lags,ridge,'mse_logit',round(float(mse),6),'rmseprob',round(float(np.mean((yp-c[te])**2)**.5),6))
np.savez('/output/regression_data.npz',row=row,t=t,src=src,q=q,target=target,tr=tr,te=te,Y=Y)
Path('/output/study_helpers.py').write_text('''import numpy as np\ndef score(a,b):\n return [float(np.mean(np.sum(a*np.log(a/b),axis=-1))),float(np.mean(np.abs(a-b).sum(-1)/2))]\ndef softmax(a):\n a=a-a.max(1,keepdims=True);a=np.exp(a);return a/a.sum(1,keepdims=True)\n''')
